// Aggregate all platform variants into a single result
const allVariants = $input.all().map(item => {
  try {
    const parsed = JSON.parse(item.json.message.content);
    return { platform: parsed.platform, variants: parsed.variants || [] };
  } catch {
    return { platform: 'unknown', variants: [] };
  }
});

return [{ json: { allVariants, generationId: $node['Validate & Split by Platform']?.json?.generationId, brandName: $node['Validate & Split by Platform']?.json?.brandName } }];

